CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS rooms (id TEXT PRIMARY KEY, tenant_name TEXT NOT NULL, temperature REAL NOT NULL, target_temp REAL NOT NULL, sunlight TEXT NOT NULL DEFAULT 'high', electronics TEXT NOT NULL DEFAULT 'on', blinds TEXT NOT NULL DEFAULT 'open', fan TEXT NOT NULL DEFAULT 'off', ac_on BOOLEAN NOT NULL DEFAULT false, ac_started_at TIMESTAMPTZ, ac_max_minutes INTEGER, ac_max_cents INTEGER, budget_cents INTEGER NOT NULL, free_actions TEXT[] NOT NULL DEFAULT '{}', revision INTEGER NOT NULL DEFAULT 1, updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), pending_offer JSONB, active_session_id UUID, session_terms JSONB, ac_seconds INTEGER NOT NULL DEFAULT 0, last_accounted_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS agent_steps (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), room_id TEXT REFERENCES rooms(id), trigger TEXT NOT NULL, state_snapshot JSONB NOT NULL, reasoning TEXT, action TEXT, action_params JSONB, outcome TEXT, result_check TEXT, tool_result JSONB, evidence JSONB, check_status TEXT NOT NULL DEFAULT 'none', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS invoices (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), room_id TEXT REFERENCES rooms(id), session_id UUID NOT NULL UNIQUE, ac_seconds INTEGER NOT NULL, rate_cents_per_hour INTEGER NOT NULL DEFAULT 120, amount_cents INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'draft', provider_id TEXT, payment_evidence JSONB, consent_summary JSONB, provider_request_id UUID, provider_progress TEXT, processed_event_ids JSONB NOT NULL DEFAULT '[]', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
INSERT INTO rooms (id,tenant_name,temperature,target_temp,budget_cents,free_actions,sunlight,electronics) VALUES ('alice','Alice',31.2,26,300,ARRAY['blinds','fan'],'high','on'),('bob','Bob',28.4,28,150,ARRAY['fan'],'low','off'),('chen','Chen',30,25.5,240,ARRAY['blinds','fan'],'medium','on'),('dana','Dana',29.5,26.5,60,ARRAY['blinds'],'high','on') ON CONFLICT (id) DO NOTHING;
